:root {
  --red: #c0392b;
  --blue: #1a3a6b;
  --gold: #f0a500;
  --cream: #fff8ee;
  --text-dark: #1a1a2e;
  --text-light: #ffffff;
  --border: #c0392b;
}

.sparkler-tag {
  width: 300px;
  background-color: var(--blue);
  border: 4px solid var(--gold);
  border-radius: 12px;
  padding: 20px 24px;
  margin: 40px auto;
  font-size: 14px;
  color: var(--text-light);
}

.tag-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.star {
  color: var(--gold);
  font-size: 20px;
}

.tag-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-light);
  letter-spacing: 1px;
  margin: 0;
}

.tag-date {
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: var(--gold);
  letter-spacing: 2px;
  text-transform: uppercase;
  margin: 0 0 12px;
}

.tag-divider {
  height: 3px;
  background-color: var(--red);
  border-radius: 2px;
  margin-bottom: 14px;
}

.tag-details {
  list-style: none;
  padding: 0;
  margin: 0 0 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--cream);
  border-radius: 6px;
  padding: 6px 12px;
  color: var(--text-dark);
}

.detail-label {
  font-weight: 700;
  font-size: 13px;
  color: var(--red);
}

.detail-value {
  font-size: 13px;
  color: var(--text-dark);
}

.tag-footer {
  text-align: center;
  font-size: 13px;
  font-weight: 600;
  color: var(--gold);
  border-top: 2px dashed var(--gold);
  padding-top: 10px;
}
